/// <summary>
/// This class used for extension of VendProductReceiptLineEntity.
/// </summary>
[ExtensionOf(tableStr(VendProductReceiptLineEntity))]
internal final class METVendProductReceiptLineEntity_Extension
{
}

Method.Source:
/// <summary>
/// This method used for populating a value to the METGSTPercent computed coloumn.
/// </summary>
/// <returns>The value of the <c>GST value</c> </returns>
public static str getGST()
{
    str taxcode = SysComputedColumn::returnField(
        tableStr(VendProductReceiptLineEntity),
        identifierStr(PurchLine),
        fieldStr(PurchLine, TaxGroup));

    str gstPrcnt = strFmt("SELECT top 1 TAXVALUE " +
                            "FROM TaxData " +
                            "WHERE TaxCode = %1 " +
                            "AND (TaxFromDate = '1900-01-01 00:00:00.000' " +
                            "OR (TaxFromDate <= CAST(GETDATE() AS DATE) AND TaxToDate >= CAST(GETDATE() AS DATE)))",
                            taxcode);

    return gstPrcnt;
}
